/**
 * Bài 41 — 就職活動 (Tìm việc) · TIẾP SAU SÁCH, BÀI ĐẦU TIÊN CẤP N2 (xem ../SOAN-BAI.md mục 8). Chặng 41–45 (Bài 45 = kiểm tra chặng).
 * Người học đã xong Bài 1–15 (ポイント 1–124), N4 (Bài 16–25) và N3 (Bài 26–40): kính ngữ cơ bản (Bài 24) + kính ngữ công sở đầy đủ
 * (Bài 37), ～うちに・～間に・～最中に (Bài 26), ～によって (nguyên nhân — Bài 27), ～とのことだ (Bài 30), ～に基づいて・～をもとに
 * (Bài 33), ～させていただく (Bài 35), ～というのは・～とは (Bài 36)… KHÔNG dạy lại — gặp trong câu là ôn (ghi "ôn: Bài X").
 *
 * Ngữ pháp N2 của bài (tiêu đề OUTLINE): ① ～際(に)／～際は／～際の N (Vる・Vた・Nの — "khi, lúc" trang trọng; Vる際 ↔ Vた際) ·
 * ② ～に際して／～に際し／～に際しての N (N・Vる — nhân dịp một việc đặc biệt, thường một lần) · ③ ～にあたって／～にあたり／
 * ～にあたっての N (N・Vる — đứng trước một việc quan trọng: chuẩn bị, quyết tâm, lời chào) · ④ ～をきっかけに(して)／～をきっかけ
 * として／～がきっかけで／～きっかけになる (khởi đầu của một thay đổi, kể cả chuyện nhỏ, đời thường) · ⑤ ～を契機に(して)／～を契機
 * として (cùng họ, NHẬN RA + dùng trong văn viết: sự kiện lớn, bước ngoặt) + ～を機に (nhân dịp — mốc đời người) · ⑥ BẢNG PHÂN BIỆT
 * 際に ↔ とき ↔ に際して ↔ にあたって (độ trang trọng, việc đặc biệt/một lần, nói/viết) · ⑦ BẢNG PHÂN BIỆT をきっかけに ↔ を契機に ↔
 * を機に ↔ によって (khởi đầu ↔ nguyên nhân trực tiếp). Cùng họ nhận ra (chỉ một dòng): ～に先立って.
 * Từ vựng: 66 từ N2 là chính (một số từ N1 hay gặp trong tin tuyển dụng có ghi), 5 nhóm: quy trình tìm việc, tự phân tích & PR bản thân,
 * phỏng vấn, công ty & điều kiện làm việc, "きっかけ" & ý chí — kèm bảng TỪ DỄ NHẦM (類義語) và KẾT HỢP TỪ (コロケーション).
 * Từ đã học KHÔNG lặp: 面接・履歴書・応募・募集・就職する・正社員 (Bài 16), 成績・挑戦・転勤 (Bài 21), 長所・人事部・インターンシップ・
 * 会社訪問 (Bài 24), 専攻する・締め切り・提出する (Bài 26), 積極的 (Bài 28), 資格・社会人・業務・勤務する・希望する (Bài 30), 能力
 * (Bài 31), 分析する・項目 (Bài 33), 研修・配属・成長・前向き・記入 (Bài 35), 弊社・御社・貴社・同僚・部署・言葉遣い (Bài 37)…
 * Chữ Hán mới (24): 就 採 志 履 企 契 析 項 挑 魅 秀 柄 極 抱 薦 雇 弊 攻 型 厚 遇 貢 献 獲 — không trùng hanTu.ts, hanTu16–38.ts,
 * hanLop.ts và các bảng chữ Hán Bài 1–39 (際 Bài 26, 職 Bài 24, 募 Bài 38, 希・催 Bài 39… đã học; 業・用・説・明・試・記・選 đã có ở bảng chữ Hán
 * của Bài 1–15). Cấp JLPT của chữ theo các bảng tham khảo phổ biến (JLPT không công bố danh sách chính thức): phần lớn N2, một số
 * xếp N1 (履 析 魅 遇 貢 献 獲 弊 雇 薦) nhưng TỪ chứa chúng (履歴書・分析・魅力・待遇・貢献・獲得・弊社・雇用・推薦) là từ N2 hay gặp.
 * Thẻ chữ Hán: hanTu41.ts (HAN_TU_41).
 * Hội thoại, câu ví dụ, bài đọc, kịch bản nghe, bài mẫu ES: VIẾT MỚI 100%, không chép giáo trình / sách luyện thi / đề thi nào.
 *
 * Nhân vật (giới tính quyết định giọng đọc, theo sách p.14): nữ = パク, ワン, アンナ, メアリー, マリヤム, 山口, 木村, リン, 鈴木,
 * {佐藤先生|さとうせんせい} · nam = マルコ, ダニエル, ナタポン, カルロス, 西川, 本田先生, {小林店長|こばやしてんちょう}, {森課長|もりかちょう}, {田村|たむら}.
 * Bối cảnh N2 (mốc thời gian nhảy lên): リン (nữ, người Việt), カルロス (nam) và パク (nữ) nay là sinh viên NĂM CUỐI (四年生) khoa Kinh tế
 * {みなと大学|みなとだいがく}, cùng ゼミ của cô {佐藤先生|さとうせんせい}; ワン (nữ) đã thực tập ở công ty phần mềm さくらシステム (Bài 35/37) và
 * nhận 内定 ở đó; {森課長|もりかちょう} (nam, phòng phát triển さくらシステム) làm người phỏng vấn vòng một.
 * Người MỚI: {中村|なかむら} (nữ — {人事部|じんじぶ} さくらシステム, phụ trách tuyển dụng {採用担当|さいようたんとう}; giọng ja-nu, vai 'c') ·
 * {高橋|たかはし} (nữ — tư vấn viên キャリアセンター của trường; ja-nu, chỉ ở phần nghe / đọc) · {石井部長|いしいぶちょう} (nam — trưởng phòng
 * nhân sự さくらシステム, phỏng vấn vòng cuối; ja-nam, chỉ ở phần nghe) · アナウンサー (nam — bản tin, phần nghe 統合理解).
 * Hội thoại: role 'a'/'c' = giọng nữ, 'b'/'examiner' = giọng nam (trang tự đổi sang giọng thứ hai khi có hai người cùng giới).
 * Nghe: 'ja-nu' = nữ, 'ja-nam' = nam. Hình: tên trong scripts/hinh/fluent-catalog.json (Fluent Emoji).
 */
import type { Block, Ex, Lesson } from '@/components/sach-hoc/types';

const E = (en: string, ro: string, vi: string): Ex => ({ en, ro, vi });

/**
 * Đáp án gõ tay: viết một lần bằng {漢字|かな}, hàm sinh đủ cách viết chữ Hán / kana
 * (máy chấm đã tự bỏ dấu câu, dấu cách và đổi chữ số toàn khổ). Phần tử đầu = dạng
 * toàn chữ Hán, là đáp án hiển thị.
 */
const V = (...xs: string[]): string[] => {
  const out = new Set<string>();
  for (const x of xs) {
    const slots = x
      .split(/(\{[^|}]+\|[^}]+\})/)
      .filter(Boolean)
      .map((p) => {
        const m = /^\{([^|}]+)\|([^}]+)\}$/.exec(p);
        return m ? [m[1], m[2]] : [p];
      });
    const n = slots.filter((s) => s.length > 1).length;
    if (n <= 8) {
      let acc = [''];
      for (const s of slots) acc = acc.flatMap((a) => s.map((c) => a + c));
      acc.forEach((a) => out.add(a));
    } else {
      out.add(slots.map((s) => s[0]).join(''));
      out.add(slots.map((s) => s[s.length - 1]).join(''));
      slots.forEach((s, i) => {
        if (s.length > 1) out.add(slots.map((t, j) => (j === i ? t[1] : t[0])).join(''));
      });
    }
  }
  return [...out];
};

type Line = [who: string, role: 'a' | 'b' | 'c' | 'examiner' | 'candidate', text: string, ro: string, vi: string];
const DL = (title: string, lines: Line[]): Block => ({
  t: 'dialogue',
  title,
  lines: lines.map(([who, role, text, ro, vi]) => ({ who, role, text, ro, vi })),
});

